insert into entity_translations (translation_id, entity_type, entity_key, field_name, lang_code, translation, source_hash, updated_at, updated_by) values (60, 'loan_category', 'personal', 'description', 'si', 'වෛද්‍ය, විවාහ හෝ හදිසි මුදල් අවශ්‍යතා සඳහා. වෛද්‍යවරුන්, ඉංජිනේරුවන් සහ වෙනත් සුදුසුකම් ලත් වෘත්තීයවේදීන්ට වට්ටම් යෝජනා ක්‍රමයක්ද ස්වයංක්‍රීයව පෙන්වයි.', '0a6fcfbffa4bc655', '2026-10-16T12:57:56.2094473', 'category_migration') on conflict do nothing;
insert into entity_translations (translation_id, entity_type, entity_key, field_name, lang_code, translation, source_hash, updated_at, updated_by) values (61, 'loan_category', 'personal', 'description', 'ta', 'மருத்துவம், திருமணம் அல்லது அவசரப் பணத் தேவைகளுக்கு. மருத்துவர்கள், பொறியாளர்கள் மற்றும் தகுதியுள்ள பிற தொழில்முறையாளர்களுக்கு தள்ளுபடித் திட்டமும் தானாகவே காண்பிக்கப்படும்.', '0a6fcfbffa4bc655', '2026-10-16T12:57:56.2094473', 'category_migration') on conflict do nothing;
insert into entity_translations (translation_id, entity_type, entity_key, field_name, lang_code, translation, source_hash, updated_at, updated_by) values (62, 'loan_category', 'housing', 'description', 'si', 'ඉඩමක් මිලදී ගැනීමට, ගොඩනැගීමට හෝ අලුත්වැඩියා කිරීමට.', '66230d33900cba08', '2026-10-16T12:57:56.2094473', 'category_migration') on conflict do nothing;
insert into entity_translations (translation_id, entity_type, entity_key, field_name, lang_code, translation, source_hash, updated_at, updated_by) values (63, 'loan_category', 'housing', 'description', 'ta', 'நிலம் வாங்க, கட்ட அல்லது புதுப்பிக்க.', '66230d33900cba08', '2026-10-16T12:57:56.2094473', 'category_migration') on conflict do nothing;
